import{_ as o,a0 as i,w as r,s as p,I as a,x as e,a1 as n,A as l,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"與開放社區討論法律事宜的 7 種方式 | LCTT x X-CMD","titleTemplate":false,"description":"與開放社區討論法律事宜的 7 種方式 | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"與開放社區討論法律事宜的 7 種方式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"與開放社區討論法律事宜的 7 種方式 | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170321 7 ways to discuss legal matters with an open community","title":"與開放社區討論法律事宜的 7 種方式","tag":"201707","desc":""},"relativePath":"201707/20170321 7 ways to discuss legal matters with an open community.md","filePath":"[post].md"}'),u={name:"201707/20170321 7 ways to discuss legal matters with an open community.md"};function d(f,t,g,h,x,T){const s=i("Link");return r(),p("div",null,[t[21]||(t[21]=a("h1",{id:"與開放社區討論法律事宜的-7-種方式",tabindex:"-1"},[e("與開放社區討論法律事宜的 7 種方式 "),a("a",{class:"header-anchor",href:"#與開放社區討論法律事宜的-7-種方式","aria-label":"Permalink to “與開放社區討論法律事宜的 7 種方式”"},"​")],-1)),t[22]||(t[22]=a("blockquote",null,[a("p",null,"你的組織的律師準備好與開源社區打交道了麼？不要讓他們犯這些錯。")],-1)),t[23]||(t[23]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/images/law/LAW-Internet_construction_9401467_520x292_0512_dc.png?itok=xmtgmowQ",alt:"7 ways to discuss legal matters with an open community",title:"7 ways to discuss legal matters with an open community"})],-1)),a("p",null,[t[2]||(t[2]=e("我注意到有相當多的人嘗試與[開源推進聯盟的許可證評估社區] ",-1)),n(s,{href:"https://opensource.org/approval"},{default:l(()=>[...t[0]||(t[0]=[e("3",-1)])]),_:1}),t[3]||(t[3]=e("以及 ",-1)),n(s,{href:"https://www.apache.org/legal/"},{default:l(()=>[...t[1]||(t[1]=[e("Apache 軟件基金會的法律事務委員會",-1)])]),_:1}),t[4]||(t[4]=e("建立溝通，當輪到_你_與開放社區進行法律討論時，我想提供一些成功的提示和技巧。",-1))]),t[24]||(t[24]=m('<h3 id="不要代理人" tabindex="-1">不要代理人 <a class="header-anchor" href="#不要代理人" aria-label="Permalink to “不要代理人”">​</a></h3><p>首先，也是最重要的是，要確保進行談話的人員既是_有資格的_，也是_有授權的_。不要用代理人，這隻會讓社區沮喪，他們很快會發現你的代表總是扮演二手車推銷員的角色並且要求到後面的房間交易。顯然，法律討論將涉及公司的一個團隊，可能涉及產品管理、工程和內部諮詢。 但代表們需要能夠自己控制談話內容，不要總是引用幕後某個匿名人物的話。</p><h3 id="多邊主義" tabindex="-1">多邊主義 <a class="header-anchor" href="#多邊主義" aria-label="Permalink to “多邊主義”">​</a></h3><p>開源社區就安全合作所需的確定性達成了難得一致的共識。這種共識體現在其治理中，尤其是在他們使用的開源許可證中。所以當你提出一個新的提案時，就不像是一個普通的商業交易。這些是雙邊談判，以雙方的自由為代價來創造一個最佳妥協的和平條約。在這個討論中，你只是許多方面之一，你需要解釋為什麼你的提案對所有人都有益。寫上多邊之間的調整本質上是緩慢的，所以不要設置最後期限。無論你做什麼，不要建議對開源許可證進行更改！</p><h3 id="首先學習" tabindex="-1">首先學習 <a class="header-anchor" href="#首先學習" aria-label="Permalink to “首先學習”">​</a></h3><p>現有的共識和過程其存在是有原因的。你應該瞭解每個元素的原因，最好連同其發生的歷史一起了解，然後再提出修改。這樣，你可以在進一步發展的背景下表達你的提案，這樣你可以避免在社區歷史中受教育（浪費社區資源，降低你機會的有效性）。回看郵件列表，並向開發人員詢問歷史和來龍去脈。</p><h3 id="透明" tabindex="-1">透明 <a class="header-anchor" href="#透明" aria-label="Permalink to “透明”">​</a></h3><p>開源開發人員使用一個迭代、增量修改的過程。即使需要大的變化，它幾乎總是用一系列更小、更好的解釋或不言而喻的正確變化來實現的，這樣每個人都可以跟進並支持。你提出的更改也是如此。不要弄出新的貢獻者協議或者修改過的許可證，並期望每個人都相信你是專家、一切都是對的。你需要提供一根“紅線”（相當於法律文件的差異），記錄每個變化，並提供一個承認任何社區影響併為其辯護的理由。如果你_只是_為了你自己的利益需要一個東西，那就承認它，而不是希望沒有人會注意到。</p><h3 id="謙遜" tabindex="-1">謙遜 <a class="header-anchor" href="#謙遜" aria-label="Permalink to “謙遜”">​</a></h3><p>你是一個炙手可熱的律師，而你認為只有程序員才使用郵件列表。很明顯，對你而言他們缺乏討論的經驗，所以你安排了一個你認為是同等的代理人，簡化這一切，或者提出與社區選擇的律師進行一對一的討論。 我很抱歉地説你做的全都是錯的。由於社區的政策是多邊協商一致的，所以他們很有可能知道他們為什麼定下現在的這些決定。名單上的一些人將具有優秀的領域知識，可能會比你的更好。而且一對一這件事是終極的羞辱，就像詢問是否有一個成年人可以與你説話。</p><h3 id="不要秘密渠道" tabindex="-1">不要秘密渠道 <a class="header-anchor" href="#不要秘密渠道" aria-label="Permalink to “不要秘密渠道”">​</a></h3><p>有可能在某種領導機構，也許你認識在公司法務工作的 VP，也許你認識社區的總法律顧問。雖然在某些情況下，詢問如何操控流程的提示可能是可以接受的，但嘗試通過秘密渠道討論或協商來試圖影響甚至決定結果，那麼結果會很糟糕。你最終可能會被邀請進行一對一的討論, 但你不應該要求或期待它。</p><h3 id="成為一個成員" tabindex="-1">成為一個成員 <a class="header-anchor" href="#成為一個成員" aria-label="Permalink to “成為一個成員”">​</a></h3><p>如果你一切都做得正確，那麼社區就有可能尊重你。堅持這些。作為一名冷靜、機智的貢獻者建立你的聲譽。當人們犯你犯過的錯誤（或者已避免的）時，幫助他們。作為郵件列表社區的值得信賴的參與者，你是項目和僱主的真正資產。繼續貢獻，一些項目最終會在它們的治理中為你提供一個角色。</p>',14)),a("p",null,[a("em",null,[t[6]||(t[6]=e("這個文章的早期版本",-1)),n(s,{href:"https://meshedinsights.com/2017/02/28/engaging-communities-on-legal-matters-7-tips/"},{default:l(()=>[...t[5]||(t[5]=[e("最初發表",-1)])]),_:1}),t[7]||(t[7]=e("在 Meshed Insights 中。",-1))])]),t[25]||(t[25]=a("p",null,"（題圖： opensource.com）",-1)),t[26]||(t[26]=a("hr",null,null,-1)),t[27]||(t[27]=a("p",null,"作者簡介：",-1)),t[28]||(t[28]=a("p",null,"Simon Phipps - 計算機行業和開源老手 Simon Phipps 上線了 Public Software，一個歐洲的開源項目託管，Document Foundation 的志願者總監。他的帖子由 Patreon 贊助者贊助 - 如果你想要看更多，成為其中一個！",-1)),t[29]||(t[29]=a("hr",null,null,-1)),a("p",null,[t[9]||(t[9]=e("via: ",-1)),n(s,{href:"https://opensource.com/open-organization/17/3/legal-matters-community"},{default:l(()=>[...t[8]||(t[8]=[e("https://opensource.com/open-organization/17/3/legal-matters-community",-1)])]),_:1})]),a("p",null,[t[13]||(t[13]=e("作者：",-1)),n(s,{href:"https://opensource.com/users/simonphipps"},{default:l(()=>[...t[10]||(t[10]=[e("Simon Phipps",-1)])]),_:1}),t[14]||(t[14]=e(" 譯者：",-1)),n(s,{href:"https://github.com/geekpi"},{default:l(()=>[...t[11]||(t[11]=[e("geekpi",-1)])]),_:1}),t[15]||(t[15]=e(" 校對：",-1)),n(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[12]||(t[12]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[18]||(t[18]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[16]||(t[16]=[e("LCTT",-1)])]),_:1}),t[19]||(t[19]=e(" 原創編譯，",-1)),n(s,{href:"https://linux.cn/"},{default:l(()=>[...t[17]||(t[17]=[e("Linux中國",-1)])]),_:1}),t[20]||(t[20]=e(" 榮譽推出",-1))])])}const y=o(u,[["render",d]]);export{P as __pageData,y as default};
